<script lang="ts">
 import {onDestroy} from 'svelte';
 import {interfaceLanguage} from '$lib/i18n/context.svelte';const ui=interfaceLanguage();
 import {Pencil,Plus,Download,Upload,Layers} from 'lucide-svelte';
 import type {RailingFamily,Wall} from '@isometrico/world';
 import {railingAnchor,railingFrame,railingPiece} from '@isometrico/world';
 import type {WorldScene} from '@isometrico/world';
 import ImageEditor from '$lib/components/ImageEditor.svelte';
 import SpriteThumbnail from '$lib/components/SpriteThumbnail.svelte';
 import {decodePaletteImage,encodePalettePNG} from './palette-browser';
 import {extractRailingPiece,replaceRailingPiece,appendRailingVariant,railingRoleLabels} from './railing-template';
 import {adaptFrameToColors} from './palette';
 import {validateEditedImage,type ImageEditOptions,type ImageEditSession,type CycleSelection,type EditorPalette} from './image-edit';
 import {downloadBlob} from '$lib/storage/adventure-package';
 import type {Frame} from '../../../packages/character-generator/src/types';
 let {family=$bindable(),name,resolve,load,palette,busy=false,onimage,onchange,oncreate,onbusy,onediting}:{family?:RailingFamily;name:string;resolve:(url:string)=>string;load:(url:string)=>Promise<Blob>;palette?:EditorPalette;busy?:boolean;onimage:(pixels:Frame)=>Promise<void>;onchange:()=>void;oncreate:(style:'stone'|'metal')=>void;onbusy:(value:boolean)=>void;onediting:(value:boolean)=>void}=$props();
 let column=$state(0),axis=$state<Wall['axis']>('x'),canvas:HTMLCanvasElement|undefined=$state(),error=$state(''),file:HTMLInputElement;
 let editing=$state.raw<ImageEditSession>(),editSheet:Frame|undefined,editColumn=0,editAxis:Wall['axis']='x';
 const piece=$derived(family?.pieces[column]??family?.pieces[0]);
 const navigation=$derived(family&&editing?{name,action:family.pieces[editColumn].id,direction:editAxis,actions:family.pieces.map(p=>({value:p.id,label:ui.text(p.label)})),directions:[{value:'x',label:'↘ X'},{value:'y',label:'↙ Y'}]}:undefined);
 function png(pixels:Frame){return new Blob([new Uint8Array(encodePalettePNG(pixels))],{type:'image/png'});}
 $effect(()=>{if(family&&column>=family.pieces.length)column=0;});
 $effect(()=>{
  const node=canvas,f=family?JSON.parse(JSON.stringify(family)) as RailingFamily:undefined;if(!node||!f)return;let cancelled=false;const image=new Image();image.onload=()=>{if(cancelled)return;const context=node.getContext('2d')!;context.clearRect(0,0,node.width,node.height);context.imageSmoothingEnabled=false;
   const scene={id:'railing-preview',width:8,height:8} as WorldScene,walls:Wall[]=[];
   for(let i=0;i<5;i++)walls.push({x:i,y:0,axis:'x',kind:'railing',railingFamily:'preview'});
   for(let i=0;i<4;i++)walls.push({x:0,y:i,axis:'y',kind:'railing',railingFamily:'preview'});
   const scale=3;for(const w of walls.sort((a,b)=>a.x+a.y-b.x-b.y)){
    const p=railingPiece(scene,w,walls,f),[fx,fy,fw,fh]=railingFrame(f,p,w.axis),[ox,oy]=railingAnchor(w.axis);
    context.drawImage(image,fx,fy,fw,fh,(180+(w.x-w.y)*32-ox)*scale,(55+(w.x+w.y)*16-oy)*scale,fw*scale,fh*scale);
   }
  };image.src=resolve(f.image);return()=>{cancelled=true;};
 });
 async function run(task:()=>Promise<void>){error='';onbusy(true);try{await task();}catch(e){error=e instanceof Error?e.message:String(e);}finally{onbusy(false);}}
 async function prepare(col=column,dir=axis){if(!family)return;const sheet=await decodePaletteImage(await load(family.image)),pixels=extractRailingPiece(sheet,col,dir);editSheet=sheet;editColumn=col;editAxis=dir;column=col;axis=dir;editing={blob:png(pixels),name:`${name} · ${family.pieces[col].label}`,width:64,height:64};onediting(true);}
 async function selectEdit(s:CycleSelection){const col=family?.pieces.findIndex(p=>p.id===s.action)??-1;if(col<0||!['x','y'].includes(s.direction??''))throw Error('Pieza no válida.');await prepare(col,s.direction as Wall['axis']);}
 async function apply(blob:Blob,options:ImageEditOptions={}){if(!editSheet)return;await validateEditedImage(blob,{width:64,height:64});await onimage(replaceRailingPiece(options.palette?adaptFrameToColors(editSheet,options.palette):editSheet,editColumn,editAxis,options.pixels??await decodePaletteImage(blob)));editing=undefined;editSheet=undefined;onediting(false);}
 function close(){editing=undefined;editSheet=undefined;onediting(false);}
 async function addVariant(){if(!family||!piece)return;if(family.pieces.length>=16)throw Error('Puedes crear hasta 16 piezas por familia.');const sheet=await decodePaletteImage(await load(family.image)),pixels=appendRailingVariant(sheet,column),id=crypto.randomUUID();family={...family,originalImage:undefined,pieces:[...family.pieces,{...piece,id,label:`${piece.label.slice(0,55)} · variante`,weight:30}]};await onimage(pixels);column=family.pieces.length-1;onchange();}
 async function upload(){const blob=file.files?.[0];file.value='';if(!blob)return;await run(async()=>{await validateEditedImage(blob,{width:64,height:64});if(!family)return;const sheet=await decodePaletteImage(await load(family.image));await onimage(replaceRailingPiece(sheet,column,axis,await decodePaletteImage(blob)));});}
 onDestroy(()=>onediting(false));
</script>
<div class="railing-editor">
 {#if family&&piece}
  <div class="visual-area">
   <div class="piece-toolbar"><label>{ui.text("Pieza")}<select bind:value={column} disabled={busy}>{#each family.pieces as p,i}<option value={i}>{ui.text(p.label)}</option>{/each}</select></label><div class="axes" role="group" aria-label={ui.text("Orientación")}>{#each ['x','y'] as direction}<button aria-pressed={axis===direction} disabled={busy} onclick={()=>axis=direction as Wall['axis']}>{direction==='x'?'↘ X':'↙ Y'}</button>{/each}</div><button class="edit" disabled={busy} onclick={()=>run(()=>prepare())}><Pencil size={16}/>{ui.text("Editar en Piskel")}</button><button title={ui.text("Importar pieza PNG")} aria-label={ui.text("Importar pieza PNG")} disabled={busy} onclick={()=>file.click()}><Upload size={16}/></button><button title={ui.text("Descargar pieza PNG")} aria-label={ui.text("Descargar pieza PNG")} disabled={busy} onclick={()=>run(async()=>downloadBlob(png(extractRailingPiece(await decodePaletteImage(await load(family!.image)),column,axis)),`${name}-${piece!.id}-${axis}.png`))}><Download size={16}/></button></div>
   <div class="preview"><canvas bind:this={canvas} width="1152" height="576" aria-label={ui.text("Vista previa de tramos unidos")}></canvas><span>{ui.text("Vista previa de tramos unidos")}</span></div>
   <div class="pieces">{#each family.pieces as p,i}<button aria-pressed={column===i} disabled={busy} onclick={()=>column=i}><SpriteThumbnail image={resolve(family.image)} frame={railingFrame(family,p,axis)} width={64} height={64}/><span>{ui.text(p.label)}</span></button>{/each}<button class="add" disabled={busy||family.pieces.length>=16} onclick={()=>run(addVariant)}><Plus size={22}/><span>{ui.text("Añadir variante")}</span></button></div>
  </div>
  <aside aria-label={ui.text("Propiedades de la pieza")}><h3><Layers size={16}/>{ui.text("Propiedades de la pieza")}</h3><div class="selected-piece"><SpriteThumbnail image={resolve(family.image)} frame={railingFrame(family,piece,axis)} width={192} height={192}/></div><label>{ui.text("Nombre de la pieza")}<input maxlength="80" required bind:value={piece.label} oninput={onchange}/></label><p class="role">{ui.text(railingRoleLabels[piece.role])} · 64 × 64 px</p><label>{ui.text("Frecuencia")}<input type="number" min="0" max="1000" step="1" bind:value={piece.weight} oninput={onchange}/></label><small>{ui.text("Peso relativo entre variantes de la misma pieza. El mapa conserva la elección al recargar.")}</small><details><summary>{ui.text("Cómo encajan las piezas")}</summary><p>{ui.text("Cada pieza cubre el borde de una casilla. Retoca dentro del lienzo sin mover el apoyo ni los extremos del pasamanos. Edita las dos orientaciones para mantener el mismo estilo.")}</p><p>{ui.text("El mapa elige automáticamente inicio, centro, final y esquina. También puedes fijar una variante en un tramo concreto.")}</p></details><p class="physical">{ui.text("Media altura de una pared. Bloquea el paso entre las casillas.")}</p></aside>
 {:else}<div class="empty"><Layers size={36}/><h2>{ui.text("Crea una familia de barandas")}</h2><p>{ui.text("Parte de una plantilla y retoca sus piezas en Piskel.")}</p><div><button onclick={()=>oncreate('stone')}>{ui.text("Balaustres de piedra")}</button><button onclick={()=>oncreate('metal')}>{ui.text("Verja metálica")}</button></div></div>{/if}
 {#if error}<p role="alert" class="error">{error}</p>{/if}
</div>
<input class="hidden" bind:this={file} type="file" accept="image/png" onchange={upload}/>
{#if editing}<ImageEditor session={editing} {palette} {navigation} onselect={selectEdit} onchange={()=>{}} onapply={apply} onclose={close} saveHint="Los retoques se guardarán cuando pulses «Guardar en aventura»."/>{/if}
<style>
 .railing-editor{display:flex;flex:1;min-width:0;min-height:0;gap:14px;position:relative}.visual-area{flex:1;width:0;min-width:0;display:flex;flex-direction:column;gap:12px}.piece-toolbar{display:flex;gap:6px;align-items:center;flex-wrap:wrap}.piece-toolbar label{flex:1;min-width:150px;display:flex;gap:8px;align-items:center;margin:0}.piece-toolbar label select{flex:1}.axes{display:flex;gap:3px}.edit{margin-left:auto}.preview{flex:1;min-height:160px;border:1px solid #dae2d1;border-radius:12px;background:repeating-conic-gradient(#e6edde 0% 25%,#f3f6ed 0% 50%) 0/20px 20px;display:flex;align-items:center;justify-content:center;position:relative;overflow:hidden}.preview canvas{width:100%;height:100%;object-fit:contain;image-rendering:pixelated}.preview>span{position:absolute;bottom:10px;left:14px;font-size:11px;color:#63745b}.pieces{display:flex;gap:8px;overflow:auto;padding-bottom:4px;flex-shrink:0}.pieces button{width:104px;flex-shrink:0;display:flex;flex-direction:column;justify-content:center;min-height:100px}.pieces span{font-size:10px;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.pieces .add{border-style:dashed}aside{flex:0 0 260px;min-width:0;overflow:auto;border:1px solid #dce4d4;border-radius:12px;padding:16px;background:#fcfdf9;box-sizing:border-box}h3{display:flex;align-items:center;gap:8px;font-size:13px;margin:0 0 12px}.selected-piece{height:170px;display:flex;align-items:center;justify-content:center;margin-bottom:12px;background:#edf2e5;border-radius:8px}label{display:flex;flex-direction:column;gap:6px;margin:12px 0 6px;font-size:12px}input,select{width:100%;font:inherit;font-size:12px;color:inherit;background:white;border:1px solid #d6dfcd;border-radius:7px;padding:8px;box-sizing:border-box;min-width:0}button{display:inline-flex;align-items:center;justify-content:center;gap:6px;font:inherit;font-size:12px;color:inherit;border:1px solid #d6dfcd;border-radius:7px;padding:8px;background:#fff;cursor:pointer}button:hover:not(:disabled),button[aria-pressed=true]{background:#e8efdd;border-color:#a9bf94}button:disabled{opacity:.45;cursor:default}.role,small,details p,.physical{font-size:11px;line-height:1.6;color:#6c7f60}.role{margin:6px 0}details{margin-top:20px}summary{cursor:pointer;font-size:12px}.physical{padding-top:14px;border-top:1px solid #dce4d4}.empty{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;border:1px dashed #cad8bc;border-radius:12px}.empty h2{font-size:20px}.empty p{font-size:13px;color:#6c7f60}.empty>div{display:flex;gap:10px}.hidden{display:none}.error{position:absolute;bottom:0;background:#fbeae3;color:#963f31;padding:8px 12px;border-radius:8px;font-size:12px}button:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:2px solid #74994e;outline-offset:2px}@media(max-width:950px){.railing-editor{flex-direction:column;overflow:auto}.visual-area{flex:none;width:100%;min-height:380px}aside{flex:none;width:100%;display:grid;grid-template-columns:1fr 1fr;gap:6px 14px;overflow:visible}aside h3,aside details,aside .physical{grid-column:1/-1}.selected-piece{grid-row:2/6;height:190px}.piece-toolbar .edit{margin-left:0}.empty{min-height:300px}}@media(max-width:500px){aside{display:block}.selected-piece{height:150px}.piece-toolbar label{flex-basis:100%}}
</style>
